spans = []
def prot(m):
    spans.append(m.group(0)); return f"\x00{len(spans)-1}\x00"
t = re.sub(r'\$\$.*?\$\$', prot, t, flags=re.S)
t = re.sub(r'\$(?!\s)[^$\n]*?\$', prot, t)
t = re.sub(r'`[^`\n]*`', prot, t)

def group(m):
    s, content = m.start(), m.group(1)
    before = t[s-1] if s else ''
    if re.search(CJK, content) or re.match(CJK, before):
        return '（' + content + '）'
    return m.group(0)
t = re.sub(r'\(([^()]*)\)', group, t)

M = {'?':'？','!':'！',':':'：',';':'；',',':'，'}
t = re.sub(r'(?:(?<=['+CJK+r'])|(?=['+CJK+r']))([?!:;,])', lambda m: M[m.group(1)], t)

def quotes(line):
    out, op = [], True
    for ch in line:
        if ch == '"': out.append('\u201c' if op else '\u201d'); op = not op
        else: out.append(ch)
    return ''.join(out)
