<script>
(function () {
  "use strict";
  var root = document.documentElement;
  var STORE = "sky-view", THEME = "sky-theme";

  /* ---- view mode ---- */
  var buttons = Array.prototype.slice.call(document.querySelectorAll(".seg button"));
  function setView(v) {
    root.setAttribute("data-view", v);
    buttons.forEach(function (b) { b.setAttribute("aria-pressed", String(b.dataset.v === v)); });
    try { localStorage.setItem(STORE, v); } catch (e) {}
  }
  buttons.forEach(function (b) { b.addEventListener("click", function () { setView(b.dataset.v); }); });

  /* ---- theme ---- */
  var themeBtn = document.getElementById("theme");
  function setTheme(t) {
    root.setAttribute("data-theme", t);
    try { localStorage.setItem(THEME, t); } catch (e) {}
  }
  themeBtn.addEventListener("click", function () {
    setTheme(root.getAttribute("data-theme") === "dark" ? "light" : "dark");
  });

  /* ---- restore prefs ---- */
  var savedView = null, savedTheme = null;
  try { savedView = localStorage.getItem(STORE); savedTheme = localStorage.getItem(THEME); } catch (e) {}
  if (savedView === "split" || savedView === "en" || savedView === "zh") setView(savedView);
  if (savedTheme === "dark" || savedTheme === "light") setTheme(savedTheme);
  else if (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) setTheme("dark");

  /* ---- keyboard ---- */
  document.addEventListener("keydown", function (e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    var tag = (e.target && e.target.tagName) || "";
    if (tag === "INPUT" || tag === "TEXTAREA") return;
    if (e.key === "1") setView("split");
    else if (e.key === "2") setView("en");
    else if (e.key === "3") setView("zh");
    else if (e.key === "t" || e.key === "T") themeBtn.click();
  });

  /* ---- scroll progress ---- */
  var bar = document.getElementById("progress");
  function tick() {
    var max = document.documentElement.scrollHeight - window.innerHeight;
    bar.style.width = (max > 0 ? (window.scrollY / max) * 100 : 0) + "%";
  }
  window.addEventListener("scroll", tick, { passive: true });
  window.addEventListener("resize", tick);
  tick();

  /* ---- section scroll-spy ---- */
  var links = {};
  Array.prototype.forEach.call(document.querySelectorAll("nav a"), function (a) {
    links[a.getAttribute("href").slice(1)] = a;
  });
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        var a = links[en.target.id];
        if (!a) return;
        if (en.isIntersecting) {
          Object.keys(links).forEach(function (k) { links[k].removeAttribute("aria-current"); });
          a.setAttribute("aria-current", "true");
        }
      });
    }, { rootMargin: "-45% 0px -50% 0px" });
    Array.prototype.forEach.call(document.querySelectorAll("section.pair"), function (s) { io.observe(s); });
  }
})();
</script>
