"""Strip all comments (line + block, incl. KDoc) from a Kotlin file.

String/char literals are tokenized so that '//' or '/*' inside them is never
treated as a comment. Lines that become empty purely because a comment was
removed are dropped; genuinely blank source lines are preserved.
"""
import sys


def tokenize(src):
    """Return list of (text, kind) spans where kind is 'code' or 'comment'."""
    spans = []
    i, n = 0, len(src)

    def flush(text, kind):
        if not text:
            return
        if spans and spans[-1][1] == kind:
            spans[-1][0] += text
        else:
            spans.append([text, kind])

    buf = []
    while i < n:
        two = src[i:i + 2]
        if two == '//':                                  # line comment
            flush(''.join(buf), 'code'); buf = []
            j = src.find('\n', i)
            j = n if j == -1 else j                      # keep the newline
            spans.append([src[i:j], 'comment'])
            i = j
        elif two == '/*':                                # block comment (nestable)
            flush(''.join(buf), 'code'); buf = []
            depth, j = 1, i + 2
            while j < n and depth:
                if src.startswith('/*', j):
                    depth += 1; j += 2
                elif src.startswith('*/', j):
                    depth -= 1; j += 2
                else:
                    j += 1
            spans.append([src[i:j], 'comment'])
            i = j
        elif src[i] in '"\'':                            # string / char literal
            q, j = src[i], i + 1
            while j < n:
                if src[j] == '\\':
                    j += 2
                elif src[j] == q:
                    j += 1; break
                elif src[j] == '\n':
                    break                                # defensive: unterminated
                else:
                    j += 1
            buf.append(src[i:j]); i = j
        else:
            buf.append(src[i]); i += 1
    flush(''.join(buf), 'code')
    return spans


def strip(src):
    out = []
    for text, kind in tokenize(src):
        if kind == 'code':
            out.append(text)
    code = ''.join(out)

    # Now drop lines that only ever held a comment.
    per_line_code, per_line_had_comment = {}, {}
    pos = 0
    for text, kind in tokenize(src):
        line = code[:pos].count('\n') if False else None  # placeholder
        pos += len(text) if kind == 'code' else 0
    # Recompute properly: walk spans tracking current line in the *original*.
    orig_lines = src.split('\n')
    code_lines = code.split('\n')
    had_comment = [False] * len(orig_lines)
    # Map original lines -> had_comment by walking spans over the original text.
    oline = 0
    pos = 0
    for text, kind in tokenize(src):
        nl = text.count('\n')
        if kind == 'comment':
            for k in range(oline, oline + nl + 1):
                if k < len(had_comment):
                    had_comment[k] = True
        oline += nl
        pos += len(text)

    result = []
    for idx, cl in enumerate(code_lines):
        if cl.strip() == '':
            if idx < len(had_comment) and had_comment[idx]:
                continue                                   # was a comment-only line
            result.append(cl)
        else:
            result.append(cl.rstrip())
    return '\n'.join(result)


if __name__ == '__main__':
    src = open(sys.argv[1]).read()
    sys.stdout.write(strip(src))
