            i = j
        elif two == '/*':                                # block comment (nestable)
            flush(''.join(buf), 'code'); buf = []
            depth, j = 1, i + 2
            while j < n and depth:
                if src.startswith('/*', j):
                    depth += 1; j += 2
                elif src.startswith('*/', j):
                    depth -= 1; j += 2
                else:
                    j += 1
            spans.append([src[i:j], 'comment'])
            i = j
        elif src[i] in '"\'':                            # string / char literal
            q, j = src[i], i + 1
            while j < n:
                if src[j] == '\\':
                    j += 2
                elif src[j] == q:
                    j += 1; break
                elif src[j] == '\n':
                    break                                # defensive: unterminated
                else:
                    j += 1
            buf.append(src[i:j]); i = j
        else:
            buf.append(src[i]); i += 1
    flush(''.join(buf), 'code')
    return spans


def strip(src):
    spans = tokenize(src)
    kinds = []
    for text, kind in spans:
        kinds.extend([kind] * len(text))

    out = []
    pos = 0
    for line in src.split('\n'):
        seg = kinds[pos:pos + len(line)]
        pos += len(line) + 1                             # +1 for the '\n'
        code_part = ''.join(c for c, k in zip(line, seg) if k == 'code')
        had_comment = 'comment' in seg
