private fun LensSelectorRow(
    cameras: List<CameraInfo>,
    selectedCameraId: String,
    selectedPhysicalId: String?,
    onLensSelected: (id: String, physicalId: String?) -> Unit,
    modifier: Modifier = Modifier
) {
    Row(
        modifier = modifier
            .background(Color.Black.copy(alpha = 0.4f), CircleShape)
            .padding(horizontal = 8.dp, vertical = 4.dp),
        horizontalArrangement = Arrangement.spacedBy(12.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        cameras.find { it.facing == CameraCharacteristics.LENS_FACING_FRONT }?.let { frontCamera ->
            LensButton(
                label = "F",
                isSelected = selectedCameraId == frontCamera.id && selectedPhysicalId == null,
                onClick = { onLensSelected(frontCamera.id, null) }
            )
        }

        cameras.filter { it.isPhysical }
            .distinctBy { it.zoomLabel }
            .forEach { camera ->
                LensButton(
                    label = camera.zoomLabel,
                    isSelected = selectedPhysicalId == camera.physicalId,
                    onClick = { onLensSelected(camera.id, camera.physicalId) }
                )
            }
    }
}

@Composable
private fun LensButton(label: String, isSelected: Boolean, onClick: () -> Unit) {
    Surface(
        onClick = onClick,
        color = if (isSelected) MaterialTheme.colorScheme.primary else Color.Transparent,
        shape = CircleShape,
        modifier = Modifier.size(40.dp)
    ) {
        Box(contentAlignment = Alignment.Center) {
            Text(
                text = label,
                color = if (isSelected) Color.Black else Color.White,
                style = MaterialTheme.typography.labelMedium
            )
        }
    }
}

fun processCaptureInBackground(
    context: Context,
    byteBuffer: ByteBuffer,
    width: Int,
    height: Int,
    timestamp: Long,
    readbackTime: Long,
    shutterStartTime: Long,
    metadata: CaptureMetadata
) {
    try {
        val t0 = System.currentTimeMillis()
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        byteBuffer.rewind()

        bitmap.copyPixelsFromBuffer(byteBuffer)
        val t1 = System.currentTimeMillis()

        saveBitmapToGallery(context, bitmap, metadata, shutterStartTime, readbackTime, t1 - t0)
        bitmap.recycle()

        val t2 = System.currentTimeMillis()
        Log.d(TAG, "[PERF_CAPTURE] res=${width}x${height} total=${t2 - shutterStartTime}ms wait=${t0 - shutterStartTime}ms copy=${t1 - t0}ms write=${t2 - t1}ms readback=${readbackTime}ms")
    } catch (e: Exception) {
        Log.e(TAG, "capture Background capture failed: ${e.message}", e)
    }

